<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { NAlert,NButton,NIcon,NInput,NPopconfirm,useMessage } from 'naive-ui'
import { Link,Refresh } from '@vicons/tabler'
import { api,bytes,stamp } from '../api'
import { cycleStamp,recoveryToken,subscriptionState } from '../featureState'
import CopyField from './CopyField.vue'
defineEmits<{renew:[]}>()
defineProps<{me:any;zone?:string}>()
const state=reactive(subscriptionState()),busy=ref(false),loading=ref(false),error=ref(''),original=ref(''),message=useMessage()
const link=computed(()=>state.path?location.origin+state.path:'')
const telegram=ref<any[]>([]),telegramError=ref('')
const telegramLink=(p:any)=>'tg://proxy?'+new URLSearchParams({server:p.server,port:String(p.port),secret:p.secret}).toString()
async function load(){loading.value=true;error.value='';try{await state.load(()=>api('/api/me/subscription'))}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(()=>{load();api<any[]>('/api/me/telegram').then(data=>telegram.value=data).catch(e=>telegramError.value=e.message)})
async function rotate(){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/api/me/subscription-token',{method:'POST'});state.path=result.path;state.needsRecovery=false;original.value='';message.success('订阅链接已重置，旧链接已失效')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function recover(){if(busy.value)return;busy.value=true;error.value='';try{const token=recoveryToken(original.value);await api('/api/me/subscription/recover',{method:'POST',body:JSON.stringify({token})});await state.load(()=>api('/api/me/subscription'));original.value='';message.success('原订阅链接已恢复显示')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">SUBSCRIPTION</span><h1>我的订阅</h1><p>原订阅链接会在刷新、重新登录后保持显示。</p></div><div class="button-row"><n-button type="primary" @click="$emit('renew')">续期套餐</n-button><n-button :loading="loading" @click="load">刷新</n-button></div></div><section class="stat-grid three"><article class="stat-card"><span class="stat-label">本周期已用</span><strong>{{bytes(me.used_bytes)}}</strong><small>已应用节点计费倍率</small></article><article class="stat-card"><span class="stat-label">剩余额度</span><strong>{{bytes(Math.max(me.quota_bytes-me.used_bytes,0))}}</strong><small>本周期额度 {{bytes(me.quota_bytes)}}</small></article><article class="stat-card"><span class="stat-label">下次流量重置</span><strong class="date-stat">{{me.next_reset_at?cycleStamp(me.next_reset_at,zone||'UTC'):'尚未开通'}}</strong><small>{{zone||'面板时区'}} · 到期 {{me.expires_at?stamp(me.expires_at):'不限'}}</small></article></section><article class="surface subscription-card"><span class="subscription-icon"><n-icon :component="Link" size="30"/></span><h2>客户端订阅链接</h2><p class="muted">支持面板已配置的协议，请使用支持对应协议及版本的客户端。</p><n-alert type="info" class="space-bottom">订阅链接等同于访问凭据，请勿转发。管理员和普通账号均需启用、未到期且有剩余额度，节点还须符合套餐范围。</n-alert><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><CopyField v-if="link" :value="link" label="客户端订阅链接"/><n-alert v-if="state.needsRecovery" type="warning" class="space-bottom">这是升级前的订阅链接。请粘贴原链接恢复显示，原链接继续有效。如果已遗失，请手动重置一次。</n-alert><form v-if="state.needsRecovery" @submit.prevent="recover"><n-input v-model:value="original" placeholder="粘贴原订阅链接或令牌" :input-props="{autocomplete:'off'}"/><n-button style="margin:12px 0" :loading="busy" :disabled="!original.trim()" attr-type="submit">恢复原链接</n-button></form><n-popconfirm @positive-click="rotate"><template #trigger><n-button type="primary" :loading="busy" :disabled="loading"><template #icon><n-icon :component="Refresh"/></template>重置订阅链接</n-button></template>重置后，之前的订阅链接立即失效。确定继续？</n-popconfirm><p class="small muted">链接由服务器加密保存；仅在你明确重置时更换。</p></article><article v-if="telegram.length||telegramError" class="surface" style="margin-top:24px"><h2>Telegram 专用代理</h2><n-alert v-if="telegramError" type="error">{{telegramError}}</n-alert><div v-for="p in telegram" :key="p.name" style="margin:16px 0"><strong>{{p.name}}</strong><CopyField :value="telegramLink(p)" label="Telegram 代理链接"/></div><p class="muted">每个实例绑定你的账户；额度用尽或到期后停止下发。链接含有专用密钥，请保密。</p></article></template>
